(() => {
  'use strict';
  const S = window.STORY;
  const $ = (q, root = document) => root.querySelector(q);
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const main = $('#main'), audio = $('#soundtrack'), dialog = $('#chapters-dialog');
  const chapters = [
    {title:'Один комментарий',sub:'TikTok, личка и наш Discord',icon:'♡',start:1,end:3},
    {title:'Первое «рядом»',sub:'Май. Челябинск. Мы.',icon:'✿',start:4,end:6},
    {title:'Навстречу друг другу',sub:'Работа, билеты и наша квартира',icon:'✈',start:7,end:8},
    {title:'Наш маленький мир',sub:'Авиапарк, кино и дорога домой',icon:'⌂',start:9,end:12},
    {title:'Города и воспоминания',sub:'Челябинск, Петербург и кораблик',icon:'⚓',start:13,end:15},
    {title:'Твой особенный день',sub:'Сентябрь. Сюрприз для тебя.',icon:'☆',start:16,end:17},
    {title:'Там, где ты — дом',sub:'Нахабино и наше продолжение',icon:'♥',start:18,end:21}
  ];
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem('polina-story-v1') || '{}'); } catch {}
  let step = 0, furthest = Math.max(0, Math.min(21, Number(saved.furthest) || 0));
  let resume = Math.max(0, Math.min(21, Number(saved.step) || 0));
  let dispose = [], token = 0, mapMove = null, jump = null, toastTimer;
  const later = (fn, ms) => { const t = setTimeout(fn, ms); dispose.push(() => clearTimeout(t)); return t; };
  const every = (fn, ms) => { const t = setInterval(fn, ms); dispose.push(() => clearInterval(t)); return t; };
  const listen = (el, type, fn, options) => { el.addEventListener(type, fn, options); dispose.push(() => el.removeEventListener(type, fn, options)); };
  function storeProgress() { try { localStorage.setItem('polina-story-v1', JSON.stringify({step:resume,furthest})); } catch {} }
  function toast(message) { clearTimeout(toastTimer); $('#toast').textContent=message; $('#toast').classList.add('visible'); toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200); }
  function playMusic() {
    if (!S.music.src) { toast('Пришли свой трек — и здесь будет ваша музыка ♡'); return; }
    audio.play().catch(()=>toast('Нажми на кнопку музыки ещё раз. Если не включается — проверим файл.'));
  }
  function pauseMusic() { audio.pause(); }
  if (S.music.src) audio.src=S.music.src;
  audio.volume=S.music.volume ?? .35;
  $('#volume').value=String(audio.volume);
  $('#track-title').textContent=S.music.title;
  $('#track-state').textContent=S.music.src?'нажми, чтобы включить':'ждёт твой трек';
  $('#volume').addEventListener('input',e=>audio.volume=Number(e.target.value));
  $('#music-toggle').addEventListener('click',()=>audio.paused?playMusic():pauseMusic());
  audio.addEventListener('play',()=>{document.body.classList.add('playing');$('#music-toggle').textContent='Ⅱ';$('#music-toggle').setAttribute('aria-label','Приостановить музыку');$('#track-state').textContent='играет для нас';});
  audio.addEventListener('pause',()=>{document.body.classList.remove('playing');$('#music-toggle').textContent='▶';$('#music-toggle').setAttribute('aria-label','Включить музыку');$('#track-state').textContent=S.music.src?'на паузе':'ждёт твой трек';});
  audio.addEventListener('error',()=>toast('Не удалось открыть музыку. Проверим путь к аудиофайлу.'));
  function icon(name, filled=false) {
    const paths={
      heart:'<path d="M12 21 3.4 12.8C-2 7.4 5.8.2 12 6.1 18.2.2 26 7.4 20.6 12.8Z"/>',
      chat:'<path d="M21 11c0 4.7-4 8.3-9 8.3-1.1 0-2.2-.2-3.2-.6L4 21l.8-4.3C3 15.2 2 13.2 2 11c0-4.7 4.3-8 10-8s9 3.3 9 8Z"/><circle cx="7" cy="11" r=".7"/><circle cx="12" cy="11" r=".7"/><circle cx="17" cy="11" r=".7"/>',
      bookmark:'<path d="M5 3h14v19l-7-5-7 5Z"/>',
      share:'<path d="m14 3 9 8-9 8v-5C7 14 4 16 1 21c0-10 5-14 13-14Z"/>',
      home:'<path d="m2 10 10-8 10 8-2 1v11h-6v-7h-4v7H4V11Z"/>',
      search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',
      inbox:'<path d="M3 4h18v15H3Z"/><path d="M3 13h5l2 3h4l2-3h5"/>',
      user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3c0-7 16-7 16 0v3Z"/>',
      friends:'<circle cx="9" cy="7" r="4"/><path d="M1 22v-3c0-7 15-7 15 0v3M17 3c5 0 5 8 0 8m2 3c4 1 4 4 4 8"/>'
    };
    return `<svg class="ui-icon" viewBox="0 0 24 24" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="${filled?'1':'1.8'}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.heart}</svg>`;
  }
  const flower = `<svg viewBox="0 0 120 120" aria-hidden="true"><g fill="#fffafc" stroke="#dcbfd0" stroke-width=".8"><ellipse cx="60" cy="30" rx="13" ry="28"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(45 60 60)"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(90 60 60)"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(135 60 60)"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(180 60 60)"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(225 60 60)"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(270 60 60)"/><ellipse cx="60" cy="30" rx="13" ry="28" transform="rotate(315 60 60)"/></g><circle cx="60" cy="60" r="18" fill="#f6cd47"/><circle cx="60" cy="60" r="12" fill="none" stroke="#d5a929" stroke-dasharray="1 3" stroke-width="7"/></svg>`;
  function photoImage(src,label) { return `<div class="photo-image" ${src?`role="button" tabindex="0" data-photo="${esc(src)}" aria-label="Увеличить фото: ${esc(label)}"`:""}>${src?`<img src="${esc(src)}" alt="${esc(label)}" loading="lazy">`:`<div class="photo-placeholder"><b>♡</b>${esc(label)}<small>место для вашей фотографии</small></div>`}</div>`; }
  function photos(list, labels, single=false) { const items=list?.length?list:labels.map(()=> '');return `<div class="${single?'single-photo':'photo-grid'}">${items.map((src,i)=>`<figure class="memory-photo" style="margin:0">${photoImage(src,labels[i%labels.length])}<figcaption class="photo-caption">${esc(labels[i%labels.length])}</figcaption></figure>`).join('')}</div>`; }
  function intro(kicker,title,description='') { return `<div class="scene-intro"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`; }
  const nextButton=(label='Сохранить этот момент')=>`<div class="scene-buttons"><button class="button pink" data-action="next">${label} <span aria-hidden="true">♡</span></button></div>`;
  function footer(){return `<div class="scene-footer"><button class="back-button" data-action="back">Вернуться на страницу раньше</button><span class="scene-counter">${String(step).padStart(2,'0')} / 21</span><span>you & me ♡</span></div>`;}
  function memoryStrip(){
    const group=step<4?'chelyabinsk':step<7?'chelyabinsk':step<13?'moscow-first':step<16?'petersburg':step<18?'birthday':'moscow-again';
    const album=window.ALBUM[group];const picks=[album[0],album[Math.floor(album.length/2)],album[album.length-1]];
    return `<div class="memory-garland" aria-label="Наши фотографии на полях"><span class="garland-line"></span>${picks.map((src,i)=>`<figure class="garland-photo" style="--tilt:${[-7,4,-4][i]}deg">${photoImage(src,'Ещё один кусочек нас')}<figcaption>${['little moments','big feelings','always us ♡'][i]}</figcaption></figure>`).join('')}<span class="garland-note">жизнь прекраснее,<br>когда в ней есть ты ♡</span></div>`;
  }
  function frame(content){main.innerHTML=`<div class="breadcrumb"><span><i class="little-dot"></i>${step===0?'НАША ИСТОРИЯ, СОХРАНЁННАЯ В СЕРДЦЕ':esc(chapters.find(c=>step>=c.start&&step<=c.end)?.title||'НАША ИСТОРИЯ')}</span>${S.demo?'<span class="draft-label">РАБОЧАЯ ВЕРСИЯ</span>':'<span>только для тебя ♡</span>'}</div><section class="scene">${content}${step?memoryStrip()+footer():''}</section>`;}
  function galleryReward(title,list,labels,after='Продолжить нашу историю') { $('#game-slot').innerHTML=`${intro('ЕЩЁ ОДНО ВОСПОМИНАНИЕ',title)}${photos(list,labels,list?.length===1)}${nextButton(after)}`; }
  function go(n) {
    dispose.forEach(fn=>fn());dispose=[];token++;mapMove=null;jump=null;
    step=Math.min(21,Math.max(0,n));
    if(step){resume=step;furthest=Math.max(furthest,step);storeProgress();}
    if(!dialog.open)main.focus({preventScroll:true});
    window.scrollTo({top:0,behavior:'instant'});
    renderNav();
    const renderers=[cover,tiktok,meet,gift,timeline,()=>walk('chel'),tears,runner,()=>flight('Челябинск','Москва'),apartment,backrooms,()=>walk('moscow'),board,()=>flight('Москва','Челябинск'),()=>flight('Челябинск','Санкт-Петербург'),boat,calendar,greeting,()=>flight('Челябинск','Москва'),metro,()=>walk('nakhabino'),finale];
    renderers[step]();
    main.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.closest('.photo-image')?.insertAdjacentHTML('beforeend',`<div class="photo-placeholder"><b>♡</b>Фото скоро будет здесь<small>проверим имя файла</small></div>`);img.remove();},{once:true}));
  }
  function renderNav(){ $('#chapter-nav').innerHTML=chapters.map((c,i)=>`<button class="chapter-button ${step>=c.start&&step<=c.end?'active':''} ${furthest>c.end?'done':''}" data-go="${c.start}" ${!S.demo&&furthest<c.start?'disabled':''} ${step>=c.start&&step<=c.end?'aria-current="step"':''}><span class="chapter-icon">${c.icon}</span><span>${esc(c.title)}</span></button>`).join(''); }
  function showChapters(){ $('#chapter-list').innerHTML=chapters.map(c=>`<button class="chapter-row" data-go="${c.start}" ${!S.demo&&furthest<c.start?'disabled':''}><span>${c.icon}</span><span><strong>${esc(c.title)}</strong><small>${esc(c.sub)}</small></span></button>`).join('');$('#chapter-note').textContent=S.demo?'В черновике все главы доступны для просмотра. В подарочной версии они будут открываться по ходу игры.':'История открывается постепенно. К уже открытым главам можно возвращаться.';dialog.showModal(); }
  document.addEventListener('click', e=>{
    const nav=e.target.closest('[data-go]');if(nav&&!nav.disabled){if(dialog.open)dialog.close();go(Number(nav.dataset.go));return;}
    const action=e.target.closest('[data-action]')?.dataset.action;
    if(action==='next')go(step+1);
    if(action==='back')go(step-1);
    if(action==='cover')go(0);
    if(action==='chapters')showChapters();
    if(action==='close-dialog')dialog.close();
    if(action==='start'){if(S.music.src&&audio.paused)playMusic();go(1);}
    if(action==='resume')go(resume||1);
  });
  document.addEventListener('keydown',e=>{if(document.querySelector("dialog[open]")||e.target.matches('input,textarea,select'))return;const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0],w:[0,-1],s:[0,1],a:[-1,0],d:[1,0]};if(mapMove&&dirs[e.key]){e.preventDefault();mapMove(...dirs[e.key]);}if(jump&&[' ','ArrowUp'].includes(e.key)&&[document.body,main,$('#jump-button')].includes(e.target)){e.preventDefault();jump();}});
  function cover(){frame(`<div class="cover"><div class="cover-copy"><div class="eyebrow">СЕМЬ МЕСЯЦЕВ. ТЫСЯЧИ МОМЕНТОВ. МЫ.</div><h1>Я бы снова<br>выбрал<br><em>тебя.</em></h1><p class="cover-description">От одного «зайди в лс» до целого мира,<br>в котором моё любимое место — рядом с тобой.</p><div class="cover-actions"><button class="button" data-action="${resume?'resume':'start'}">${resume?'Продолжить с нашего момента':'Вернуться в наше начало'} <span>♡</span></button><button class="button plain" data-action="${resume?'start':'chapters'}">${resume?'Прожить всё с самого начала':'Заглянуть в главы нашей истории'}</button></div><p class="cover-caption">маленький квест для самого важного человека <span>↗</span></p></div><div class="cover-art" aria-label="Романтический альбом для Полины"><span class="art-tag">to: ${esc(S.herName)} ♡</span><span class="kiss-sticker">love<br>you!</span><div class="cover-polaroid polaroid"><div class="polaroid-art">${S.photos.cover?`<img src="${esc(S.photos.cover)}" alt="Мы вместе" style="width:100%;height:100%;object-fit:contain;position:absolute">`:'<span class="big-heart">♥</span>'}</div><p class="hand-caption">ты + я = моё любимое всё</p></div><span class="art-star">✧</span><span class="flower flower-one">${flower}</span><span class="flower flower-two">${flower}</span><span class="small-stamp">7 MONTHS OF US ♡</span></div></div><div class="cover-bottom"><span><b>♡</b> сделано только для тебя</span><span><b>✿</b> наши города и воспоминания</span><span><b>♫</b> лучше проходить в наушниках</span></div>`); }
  function phoneStatus(){return `<div class="phone-status"><strong>9:41</strong><div class="battery"><span>▮▮▮</span><svg viewBox="0 0 24 16" aria-label="Заряд батареи"><rect x="1" y="2" width="19" height="12" rx="3" fill="none" stroke="currentColor"/><rect x="3" y="4" width="15" height="8" rx="1"/><rect x="21" y="6" width="2" height="4" rx="1"/></svg></div></div><div class="island"></div>`;}
  function ttNav(active='home'){return `<nav class="tt-nav" aria-label="Навигация TikTok"><button data-tt="home" class="${active==='home'?'active':''}">${icon('home',active==='home')}Главная</button><button data-tt="friends">${icon('friends')}Друзья</button><button data-tt="create" aria-label="Добавить видео"><span class="tt-plus">+</span></button><button data-tt="inbox" class="${active==='inbox'?'active':''}">${icon('inbox')}${active==='home'?'<span class="nav-badge">1</span>':''}Входящие</button><button data-tt="profile">${icon('user')}Профиль</button></nav>`;}
  function tiktok(){
    frame(`<div class="phone-scene"><div class="phone-context"><div class="eyebrow">ВСЁ НАЧАЛОСЬ С ЭТОГО</div><h1>Одно уведомление.<br><i>Целая жизнь</i><br>после него.</h1><p>Обычная лента. Обычный день.<br>И одно сообщение, которое всё изменило.</p><p class="hand-note">А если бы ты тогда<br>не ответила?.. ♡</p></div><div class="phone-holder"><div id="phone" class="phone" aria-label="Игровой экран телефона, TikTok"></div><p class="notification-hint" id="phone-hint">Нажми на уведомление о комментарии</p></div></div>`);
    const phone=$('#phone');
    const userAvatar=`<div class="activity-avatar"><img src="${esc(S.tiktok.avatar)}" alt="Аватар тгк: wifiboy0"></div>`;
    const avatarStyle=S.tiktok.profile?`style="background-image:url('${esc(S.tiktok.profile)}')"`:'';
    function feed(){phone.className='phone';phone.innerHTML=`${phoneStatus()}<div class="tt-feed">${S.tiktok.feed?`<img src="${esc(S.tiktok.feed)}" alt="Видео в ленте TikTok">`:'<div class="feed-visual"><div class="feed-window"></div></div><div class="feed-caption">иногда всё начинается<br>с одного сообщения</div>'}<div class="tt-tabs"><span>Подписки</span><span class="active">Рекомендации</span></div><span class="tt-search">${icon('search')}</span><div class="tt-side"><div class="tt-userpic">✿</div><button data-tt="like" aria-label="Поставить лайк">${icon('heart',true)}<span id="tt-likes">24,7K</span></button><button data-tt="comment" aria-label="Открыть комментарии">${icon('chat',true)}<span>128</span></button><button data-tt="save" aria-label="Сохранить видео">${icon('bookmark',true)}<span>1 024</span></button><button data-tt="share" aria-label="Поделиться видео">${icon('share',true)}<span>317</span></button></div><div class="tt-bottom-caption"><strong>@our.little.story</strong><br>однажды это станет нашим воспоминанием ♡<br>#любовь #рекомендации<span class="music-line">♫ оригинальный звук · our.little.story</span></div></div>${ttNav()}<button class="tt-notification" data-tt="comment"><span class="activity-avatar" style="width:30px;height:30px"><img src="${esc(S.tiktok.avatar)}" alt=""></span><span class="notification-body"><strong>${esc(S.tiktok.hisHandle)}</strong><small>Прокомментировал(-а) ваше видео</small><span class="comment-text">${esc(S.tiktok.comment)}</span></span><span class="notification-time">сейчас</span></button>`;$('#phone-hint').textContent='Нажми на уведомление о комментарии';}
    function comment(){phone.querySelector('.tt-notification')?.remove();phone.querySelector('.tt-comment-panel')?.remove();phone.insertAdjacentHTML('beforeend',`<div class="tt-comment-panel"><div class="comment-head">Комментарии (1)<button data-tt="home" aria-label="Закрыть комментарии">×</button></div><div class="comment-row">${userAvatar}<div class="comment-content"><strong>${esc(S.tiktok.hisHandle)}</strong><p>${esc(S.tiktok.comment)}</p><div class="comment-meta"><span>Только что</span><button data-tt="dm">Открыть ЛС</button></div></div><span style="font-size:19px;color:#aaa">♡</span></div><div class="comment-input"><span>Добавить комментарий...</span>☺</div></div>`);$('#phone-hint').textContent='Тот самый комментарий. Открой личные сообщения.';}
    function inbox(){phone.className='phone phone-light';phone.innerHTML=`${phoneStatus()}<div class="tt-inbox-header"><button data-tt="home" aria-label="В ленту">‹</button>Входящие<span>⌕</span></div><div class="activity-tabs"><span>Вся активность</span><span>Лайки</span><span>Комментарии</span></div><p class="activity-date">Новые</p><div class="activity-item" role="button" tabindex="0" data-tt="dm">${userAvatar}<div><strong>${esc(S.tiktok.hisHandle)}</strong><p>прокомментировал(-а) ваше видео.</p><blockquote>${esc(S.tiktok.comment)}</blockquote><small style="color:#999">Только что</small></div><span class="activity-thumb">▶</span></div>${ttNav('inbox')}`;$('#phone-hint').textContent='Открой новое сообщение';}
    function dm(){phone.className='phone phone-light';phone.innerHTML=`${phoneStatus()}<div class="dm-header"><button data-tt="inbox" aria-label="Во входящие">‹</button><div class="dm-avatar"><img src="${esc(S.tiktok.avatar)}" alt=""></div><strong>${esc(S.tiktok.hisHandle)}</strong><span>⋯</span></div><p class="dm-date">Начало переписки</p><div class="dm-row"><div class="dm-avatar"><img src="${esc(S.tiktok.avatar)}" alt=""></div><div class="dm-bubble">${esc(S.tiktok.message||'Здесь будет начало вашей переписки')}</div></div><div class="dm-input"><span>Отправить сообщение...</span><span>☺ ♡</span></div><div class="tt-action-sheet"><p>И что ты сделаешь?</p><button data-tt="answer">Ответить</button><button class="ignore" data-tt="ignore">Проигнорировать</button></div>`;$('#phone-hint').textContent='Один маленький выбор, который изменил всё';}
    feed();
    listen(phone,'click',e=>{const a=e.target.closest('[data-tt]')?.dataset.tt;if(a==='home')feed();if(a==='comment')comment();if(a==='inbox')inbox();if(a==='dm')dm();if(a==='answer')go(2);if(a==='ignore'){frame(`<div class="end-choice"><span class="broken-heart">💔</span><h1>А здесь история<br><i>могла закончиться.</i></h1><p>Ни звонков до ночи. Ни билетов. Ни наших квартир.<br>Хорошо, что в нашей истории ты всё-таки ответила.</p><div class="scene-buttons"><button class="button pink" data-go="1">Дать нам ещё один шанс ♡</button></div></div>`);}if(a==='like'){const b=e.target.closest('button');b.style.color='#fe2c55';$('#tt-likes').textContent='24,8K';}if(a==='save')e.target.closest('button').style.color='#face15';if(['friends','create','profile','share'].includes(a))toast('В этой истории всё начинается с комментария ♡');});
    listen(phone,'keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role="button"]'))dm();});
  }
  function choiceMarkup(options){return `<div class="choice-grid">${options.map((o,i)=>`<button class="choice-card" data-choice="${i}"><span class="item-icon">${o.image?`<img class="item-photo" src="${esc(o.image)}" alt="${esc(o.text)}">`:o.icon}</span><strong>${esc(o.text)}</strong></button>`).join('')}</div>`;}
  function bindChoice(correct,onCorrect){let solved=false;listen($('#game-slot'),'click',e=>{const b=e.target.closest('[data-choice]');if(!b||solved)return;if(Number(b.dataset.choice)!==correct){toast('Кажется, в нашей истории было немного иначе. Попробуй ещё ♡');return;}solved=true;b.classList.add('selected');onCorrect();});}
  function meet(){frame(`${intro('ПЯТНАДЦАТЬ МИНУТ СПУСТЯ','И мы уже <i>не могли наговориться.</i>','Куда мы перешли после первых пятнадцати минут общения?')}<div id="game-slot">${choiceMarkup(S.meet.options.map((text,i)=>({text,icon:['☏','☾','☕'][i]})))}<p class="hint">Выбери то самое место для нашего первого долгого разговора</p></div>`);bindChoice(S.meet.correct,()=>{$('#game-slot').innerHTML=`<div class="discord-card"><span class="discord-logo">☏</span><h3>Наш первый Discord</h3><p>Из пятнадцати минут — в «ещё чуть-чуть побудем?»</p><div class="call-users"><div class="call-user">w</div><div class="call-user">♡</div></div><div class="call-timer">Голосовая связь установлена</div><p>${esc(S.tiktok.hisHandle)} + ${esc(S.tiktok.herHandle)}</p></div>${nextButton('Остаться в этой истории')}`;});}
  function gift(){frame(`${intro('МАЛЕНЬКИЕ ВЕЩИ, БОЛЬШИЕ ЧУВСТВА','Помнишь <i>тот самый подарок?</i>','Выбери, что ты подарила мне на день рождения.')}<div id="game-slot">${choiceMarkup(S.gift.options)}<p class="hint">Одна из этих вещей хранит наш маленький секрет.</p></div>`);bindChoice(S.gift.correct,()=>{$('#game-slot').innerHTML=`<div style="text-align:center;padding:35px"><img class="gift-reward" src="${esc(S.gift.options[S.gift.correct].image)}" alt="Тот самый плюшевый Аппа"><p style="font:31px var(--hand);margin-top:20px">Любимый подарок — потому что от тебя.</p></div>${nextButton('Листать воспоминания дальше')}`;});}
  function timeline(){frame(`${intro('ПЕРЕМОТАЕМ НЕМНОГО НАЗАД','У каждого «мы» <i>есть начало.</i>','Расставь первые события нашей истории по порядку.')}<div id="game-slot"><div class="timeline-slots" id="timeline-slots"></div><div class="timeline-options">${['Первый комментарий','Наш Discord','Поездка в Челябинск'].map((x,i)=>`<button data-event="${i}">${x}</button>`).join('')}</div><p class="hint">Нажимай на события от самого раннего к самому позднему</p></div>`);const chosen=[];const labels=['Первый комментарий','Наш Discord','Поездка в Челябинск'];function update(){$('#timeline-slots').innerHTML=[0,1,2].map(i=>`<div class="timeline-slot ${chosen[i]===undefined?'empty':''}"><b>${['Сначала','Потом','А дальше'][i]}</b>${chosen[i]===undefined?'поставь воспоминание':labels[chosen[i]]}</div>`).join('');}update();listen($('#game-slot'),'click',e=>{const b=e.target.closest('[data-event]');if(!b)return;const n=Number(b.dataset.event);if(n!==chosen.length){toast('Давай начнём с самого первого «зайди в лс» ♡');return;}chosen.push(n);b.disabled=true;update();if(chosen.length===3)$('#game-slot').insertAdjacentHTML('beforeend',nextButton('Вернуться в тот май'));});}
  function walk(key){
    const m=S.maps[key];
    frame(`${intro(esc(m.city),m.title,esc(m.description))}<div id="game-slot"><section class="real-route" id="real-route" aria-label="Прогулка по настоящим панорамам"><div class="real-route-header"><div><span class="tiny">ДОРОГА К НАМ</span><h2>${esc(m.startLabel)} <span>♡</span> домой</h2><p>${esc(m.endLabel)}</p></div><div class="route-timebox"><span class="route-timer" id="route-timer">10:00</span><button id="route-pause" aria-label="Приостановить таймер">Пауза</button></div></div><div class="route-tabs" aria-label="Режим прогулки"><button data-route-view="panorama" class="active" aria-pressed="true">Гулять по улице</button><button data-route-view="map" aria-pressed="false">Карта пути</button>${m.reference?'<button data-route-view="reference" aria-pressed="false">Узнаёшь наш дом?</button>':''}</div><div class="pano-window"><iframe id="route-frame" src="${esc(m.panoramaStart)}" title="${esc(m.city)}: прогулка от ${esc(m.startLabel)}" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><iframe id="route-map-frame" src="about:blank" title="Пеший маршрут к нашему дому" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" hidden></iframe><div id="route-reference" hidden>${m.reference?`<img src="${esc(m.reference)}" alt="Ориентир: наш дом из присланного снимка"><span>Наш ориентир ♡</span>`:''}</div></div><div class="route-live-status" id="route-live-status" role="status">Загружаем панораму Яндекса…</div><div class="route-tools"><button id="route-reset">Вернуться к магазину</button><button id="route-hint">Нужна подсказка</button><button id="route-expand">Развернуть</button></div><div class="route-mission"><p id="route-mission-text">Оглядись и иди белыми стрелками на самой панораме. Когда узнаешь наш дом — нажми «Я дошла».</p><button class="button pink" id="route-arrived">Я дошла ♡</button></div><div id="route-quiz"></div></section><p class="route-years">${esc(m.years)}</p><p class="route-coverage">${esc(m.coverage)}</p><p class="route-open-link">Если карта не открылась, <a id="route-external" href="${esc(m.panoramaStart)}" target="_blank" rel="noopener noreferrer">открыть панораму отдельно</a>, затем вернуться к квесту.</p></div>`);
    const panel=$('#real-route'),iframe=$('#route-frame'),mapIframe=$('#route-map-frame'),reference=$('#route-reference'),quiz=$('#route-quiz');
    let remaining=m.seconds*1000,last=performance.now(),done=false,paused=false,currentView='panorama',hinted=false;
    function paintTime(){if(done)return;const n=Math.ceil(remaining/1000);$('#route-timer').textContent=`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
    function exitWide(){panel.classList.remove('route-expanded');document.body.classList.remove('watching-route');$('#route-expand').textContent='Развернуть';if(document.fullscreenElement===panel)document.exitFullscreen?.().catch(()=>{});}
    function view(which,home=false,reset=false){
      currentView=which;$('#route-external').textContent=which==='map'?'открыть карту отдельно':'открыть панораму отдельно';reference.hidden=which!=='reference';iframe.hidden=which!=='panorama';mapIframe.hidden=which!=='map';
      panel.querySelectorAll('[data-route-view]').forEach(b=>{const active=b.dataset.routeView===which;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
      if(which==='map'){
        if(mapIframe.getAttribute('src')==='about:blank')mapIframe.src=m.mapUrl;
        $('#route-external').href=m.mapUrl;$('#route-live-status').textContent='На карте — пеший путь от магазина к нашему дому.';
      }else if(which==='panorama'){
        if(home||reset){iframe.src=home?m.panoramaHome:m.panoramaStart;$('#route-live-status').textContent='Загружаем панораму Яндекса…';}
        else $('#route-live-status').textContent='Продолжай с того же места: белые стрелки ведут по улице.';
        $('#route-external').href=home?m.panoramaHome:iframe.getAttribute('src');
      }else $('#route-live-status').textContent='Фотография-ориентир. Прогулка продолжается во вкладке «Гулять по улице».';
    }
    function finish(){
      if(done)return;done=true;exitWide();iframe.src='about:blank';mapIframe.src='about:blank';
      if(key==='chel')galleryReward('Вот он. <i>Наш четвёртый подъезд.</i>',S.photos.chelyabinsk,['Наш первый Челябинск','Там, где мы были рядом'],'Запомнить этот день');
      else if(key==='moscow')galleryReward('Наш дом на Вокзальной.<br><i>Наш маленький мир.</i>',S.photos.moscow,['Наша московская жизнь','Любимый обычный день'],'Оставить фото на память');
      else galleryReward('Пятый подъезд.<br><i>Мы дома.</i>',S.photos.nakhabino,['Наша квартира в Нахабино','Счастье в простых моментах'],'Открыть последнее письмо');
    }
    function showQuiz(){
      if(done)return;exitWide();
      const question=m.arrivalType==='house'?'И какой же дом был нашим?':'Какой подъезд хранит нашу историю?';
      const hunt=m.arrivalType==='entrance-photo';
      quiz.innerHTML=`<div class="arrival-quiz"><span class="tiny">ЕЩЁ ОДНО МАЛЕНЬКОЕ ВОСПОМИНАНИЕ</span><h3 tabindex="-1">${question}</h3>${hunt?`<div class="entry-hunt"><img src="${esc(m.reference)}" alt="Подъезды нашего дома: четвёртый, пятый и шестой"><button data-route-answer="0" style="left:0;width:28%" aria-label="Выбрать подъезд 4"><span>4</span></button><button data-route-answer="1" style="left:29%;width:32%" aria-label="Выбрать подъезд 5"><span>5</span></button><button data-route-answer="2" style="left:75%;width:25%" aria-label="Выбрать подъезд 6"><span>6</span></button></div><p class="hint">Нажми на область нужного входа на фотографии</p>`:`<div class="arrival-answers">${m.choices.map((text,i)=>`<button data-route-answer="${i}">${esc(text)}</button>`).join('')}</div>`}<p id="arrival-feedback" aria-live="polite"></p></div>`;
      quiz.querySelector('h3').focus({preventScroll:true});quiz.scrollIntoView({behavior:'smooth',block:'center'});
    }
    listen(iframe,'load',()=>{if(!done&&currentView==='panorama')$('#route-live-status').textContent='Панорама: двигайся белыми стрелками и оглядывайся мышью или пальцем.';});
    listen(mapIframe,'load',()=>{if(!done&&currentView==='map')$('#route-live-status').textContent='На карте — пеший путь от магазина к нашему дому.';});
    listen(panel,'click',e=>{
      const tab=e.target.closest('[data-route-view]');if(tab)view(tab.dataset.routeView);
      if(e.target.closest('#route-reset')){view('panorama',false,true);$('#route-mission-text').textContent='Ты снова у магазина. Оглядись и вспомни нашу дорогу.';}
      if(e.target.closest('#route-hint')){hinted=!hinted;$('#route-mission-text').textContent=m.hint;if(hinted){$('#route-mission-text').insertAdjacentHTML('beforeend',' <button class="near-home" id="near-home">Показать последний поворот</button>');}}
      if(e.target.closest('#near-home')){view('panorama',true);$('#route-mission-text').textContent=m.arrivalType==='house'?'Это ближайшая съёмка с улицы. Сам частный дом отмечен на карте пути.':'Ты у нашего дома. Оглянись и найди нужный вход.';}
      if(e.target.closest('#route-expand')){if(panel.classList.contains('route-expanded'))exitWide();else{panel.classList.add('route-expanded');document.body.classList.add('watching-route');$('#route-expand').textContent='Свернуть';panel.requestFullscreen?.().catch(()=>{});}}
      if(e.target.closest('#route-pause')){paused=!paused;last=performance.now();$('#route-pause').textContent=paused?'Продолжить':'Пауза';$('#route-pause').setAttribute('aria-label',paused?'Продолжить таймер':'Приостановить таймер');}
      if(e.target.closest('#route-arrived'))showQuiz();
      const answer=e.target.closest('[data-route-answer]');if(answer){if(Number(answer.dataset.routeAnswer)===m.correct)finish();else{$('#arrival-feedback').textContent='Почти. Вспомни нашу дверь — попробуй ещё раз ♡';}}
    });
    listen(document,'keydown',e=>{if(e.key==='Escape')exitWide();});
    listen(document,'fullscreenchange',()=>{if(!document.fullscreenElement){panel.classList.remove('route-expanded');document.body.classList.remove('watching-route');$('#route-expand').textContent='Развернуть';}});
    listen(document,'visibilitychange',()=>{last=performance.now();});
    every(()=>{if(done)return;const now=performance.now();if(!paused&&!document.hidden)remaining=Math.max(0,remaining-(now-last));last=now;paintTime();if(remaining<=0){done=true;exitWide();iframe.src='about:blank';mapIframe.src='about:blank';$('#game-slot').innerHTML=`${intro('ДОРОГА НИКУДА НЕ ИСЧЕЗЛА','Давай <i>прогуляемся ещё раз.</i>','Можно начать заново и воспользоваться подсказкой у последнего поворота.')}<div class="scene-buttons"><button class="button pink" data-go="${step}">Попробовать снова ♡</button></div>`;}},250);
    dispose.push(()=>{iframe.src='about:blank';mapIframe.src='about:blank';exitWide();});paintTime();
  }

  function tears(){frame(`${intro('Я УЛЕТАЮ. НО НЕ ИЗ ТВОЕЙ ЖИЗНИ.','Тот самый <i>момент прощания.</i>','Иногда мы плачем, потому что очень-очень любим.')}<div id="game-slot"><div class="tears-field">${[[14,13],[64,8],[35,42],[75,59],[9,67],[49,73]].map((p,i)=>`<button class="tear" data-tear="${i}" aria-label="Поймать слезинку ${i+1}" style="--x:${p[0]}%;--y:${p[1]}%;--delay:-${i/3}s">💧</button>`).join('')}</div><div class="tear-meter"><span style="width:0%"></span></div><p class="hint" id="tear-count">Собери 6 слезинок, чтобы открыть наше фото</p></div>`);let count=0;listen($('#game-slot'),'click',e=>{const b=e.target.closest('[data-tear]');if(!b)return;b.remove();count++;$('.tear-meter span').style.width=`${count/6*100}%`;$('#tear-count').textContent=`Слезинки: ${count} / 6`;if(count===6)galleryReward('Расстояние не умеет <i>отменять любовь.</i>',(Array.isArray(S.photos.farewell)?S.photos.farewell:[S.photos.farewell]),['Наше прощальное фото'],'Лететь дальше. Вместе.');});}
  function runner(){
    frame(`${intro('ТЕПЕРЬ ТЫ НЕМНОГО В МОЕЙ РОЛИ','Каждый заказ — <i>ближе к нашему дому.</i>','Поработай курьером: перепрыгивай препятствия и выполни семь доставок.')}<div id="game-slot"><div class="runner-wrap"><div class="runner-stats"><span>Доставки: <b id="deliveries">0</b> / 7</span><span>Цель: наш общий дом ♡</span></div><div class="runner-stage"><canvas width="780" height="300" aria-label="Игра про курьера" role="img"></canvas><div class="runner-overlay" id="runner-overlay"><h3>На смену ради нас</h3><p>Нажимай на игру или «Прыжок». На компьютере можно использовать пробел.</p><button class="button pink" id="run-start">Взять первый заказ</button></div></div><div class="scene-buttons"><button class="button light" id="jump-button">Прыжок</button></div><p class="hint">Короткая смена: 7 доставок. При неудаче можно попробовать снова.</p></div></div>`);
    const canvas=$('canvas'),ctx=canvas.getContext('2d'),overlay=$('#runner-overlay');let running=false,y=0,v=0,last=0,spawn=.9,hazards=[],deliveries=0,elapsed=0,frameId,alive=true;
    const ground=244,px=105,pw=31,ph=47;
    function draw(){ctx.clearRect(0,0,780,300);ctx.fillStyle='#fff8fc';ctx.fillRect(0,0,780,300);ctx.fillStyle='#f1dfeb';for(let i=0;i<9;i++){const x=(i*130-elapsed*35)%1040;const h=60+(i%3)*24;ctx.fillRect(x,ground-h,80,h);ctx.fillStyle='#e6c7db';for(let a=0;a<3;a++)for(let b=0;b<3;b++)ctx.fillRect(x+10+a*23,ground-h+12+b*20,9,10);ctx.fillStyle='#f1dfeb';}ctx.fillStyle='#ab849b';ctx.fillRect(0,ground,780,2);ctx.fillStyle='#dfc9d5';for(let i=0;i<25;i++)ctx.fillRect((i*40-elapsed*240%40),ground+20,16,3);const yy=ground-ph-y;ctx.fillStyle='#3b283a';ctx.fillRect(px+7,yy,19,18);ctx.fillStyle='#f33580';ctx.fillRect(px+4,yy+18,23,20);ctx.fillStyle='#31232e';const leg=running&&y===0?Math.sin(elapsed*20)*4:0;ctx.fillRect(px+5,yy+38,8,9+leg);ctx.fillRect(px+20,yy+38,8,9-leg);ctx.fillStyle='#b27b54';ctx.fillRect(px-10,yy+15,15,22);ctx.fillStyle='#ffe4f0';ctx.fillRect(px-5,yy+18,5,6);ctx.fillStyle='#ffd8c2';ctx.fillRect(px+20,yy+6,6,6);for(const h of hazards){ctx.fillStyle='#7e6b7f';ctx.fillRect(h.x,ground-h.h,h.w,h.h);ctx.fillStyle='#bda3b7';ctx.fillRect(h.x+4,ground-h.h+5,h.w-8,6);}ctx.font='14px Arial';ctx.fillStyle='#a87b96';ctx.fillText('ДОСТАВЛЯЕМ НАШЕ БУДУЩЕЕ ♡',20,28);}
    function tick(t){if(!alive)return;frameId=requestAnimationFrame(tick);const dt=Math.min((t-last)/1000||0,.035);last=t;if(!running||document.hidden){draw();return;}elapsed+=dt;v-=1600*dt;y=Math.max(0,y+v*dt);if(y===0)v=0;spawn-=dt;if(spawn<=0){hazards.push({x:810,w:26,h:31});spawn=1.65+Math.random()*.35;}for(const h of hazards)h.x-=245*dt;const hit=hazards.some(h=>h.x<px+pw-6&&h.x+h.w>px+5&&y<h.h-5);if(hit){running=false;overlay.style.display='grid';overlay.innerHTML='<h3>Небольшая пауза</h3><p>Курьеры тоже иногда спотыкаются. Давай ещё одну смену?</p><button class="button pink" id="run-start">Начать заново</button>';return;}hazards=hazards.filter(h=>{if(h.x+h.w<px&&!h.passed){h.passed=true;deliveries++;$('#deliveries').textContent=deliveries;}return h.x>-50;});if(deliveries>=7){running=false;alive=false;jump=null;cancelAnimationFrame(frameId);$('#game-slot').innerHTML=`${intro('СМЕНА ЗАКОНЧЕНА','Заработано: <i>ещё немного нашего будущего.</i>','Я работал и думал о том, как однажды мы откроем дверь своей квартиры. Вместе.')}<div class="end-heart">⌂ ♡</div>${nextButton('А теперь — встречать тебя')}`;return;}draw();}
    function start(){y=0;v=0;hazards=[];spawn=1;deliveries=0;elapsed=0;$('#deliveries').textContent='0';running=true;overlay.style.display='none';main.focus({preventScroll:true});}
    jump=()=>{if(running&&y===0)v=630;};
    listen($('#game-slot'),'click',e=>{if(e.target.closest('#run-start')){start();return;}if(e.target.closest('canvas,#jump-button'))jump?.();});
    frameId=requestAnimationFrame(tick);dispose.push(()=>{alive=false;cancelAnimationFrame(frameId);});draw();
  }
  function flight(from,to){
    frame(`${intro('БИЛЕТ В СТОРОНУ «МЫ»','Километры становятся <i>меньше.</i>',`Перенеси самолётик из города ${esc(from)} в город ${esc(to)}.`)}<div id="game-slot"><div class="flight-board" id="flight-board"><svg viewBox="0 0 760 350" preserveAspectRatio="none" aria-hidden="true"><rect width="760" height="350" fill="#eee6ef"/><path d="M-30 165Q70 95 150 145T340 92 530 140 800 52V240Q650 270 540 225T350 278 180 240 0 310Z" fill="#dcd6e5"/><path d="M-20 190Q110 85 210 160T420 185 600 100 800 145" fill="none" stroke="#f7f1f8" stroke-width="22"/><path d="M167 202Q330 25 577 119" fill="none" stroke="#e6a6c5" stroke-width="2" stroke-dasharray="6 7"/><g fill="#d0bfd1"><circle cx="105" cy="95" r="6"/><circle cx="500" cy="245" r="4"/><circle cx="670" cy="280" r="7"/></g></svg><span class="city origin"><b></b>${esc(from)}</span><button class="city destination" id="destination" aria-label="Приземлиться: ${esc(to)}"><b></b>${esc(to)}</button><button class="plane" id="plane" aria-label="Взять самолётик">✈</button></div><div class="boarding-pass"><div><span>ОТКУДА</span><b>${esc(from)}</b></div><span style="font-size:28px;color:var(--pink)">✈</span><div><span>КУДА</span><b>${esc(to)}</b></div></div><p class="hint" id="flight-hint">Можно перетащить самолёт или нажать на него, а затем на город назначения</p></div>`);
    const plane=$('#plane'),field=$('#flight-board'),destination=$('#destination');let picked=false,done=false,dragging=false;
    function land(){if(done)return;done=true;dragging=false;plane.classList.add('flying');plane.style.left='76%';plane.style.top='20%';$('#flight-hint').textContent='Посадка. Кажется, здесь нас ждёт счастье ♡';later(()=>{$('#game-slot').insertAdjacentHTML('beforeend',nextButton('Мы прилетели'));},1350);}
    listen(plane,'click',()=>{if(done)return;picked=true;$('#flight-hint').textContent=`Теперь нажми на ${to}. Тебя там ждут ♡`;plane.style.outline='3px solid #f33580';});
    listen(destination,'click',()=>picked?land():toast('Сначала возьми самолётик ♡'));
    listen(plane,'pointerdown',e=>{if(done)return;dragging=true;picked=true;plane.setPointerCapture(e.pointerId);});
    listen(plane,'pointermove',e=>{if(!dragging||done)return;const r=field.getBoundingClientRect();plane.style.left=`${Math.max(5,Math.min(95,(e.clientX-r.left)/r.width*100))}%`;plane.style.top=`${Math.max(7,Math.min(88,(e.clientY-r.top)/r.height*100))}%`;});
    listen(plane,'pointerup',e=>{if(!dragging||done)return;dragging=false;const r=destination.getBoundingClientRect();if(e.clientX>=r.left-35&&e.clientX<=r.right+35&&e.clientY>=r.top-50&&e.clientY<=r.bottom+25)land();else{$('#flight-hint').textContent=`Перенеси самолёт к ${to} или нажми на название города`;}});
    listen(plane,'pointercancel',()=>dragging=false);
  }
  function apartment(){frame(`${intro('НАША КВАРТИРА. НАШИ ПЛАНЫ.','Дорогая, <i>куда сегодня?</i>','У нас есть целый город. Но один вариант ты точно узнаешь.')}<div id="game-slot"><div class="apartment-stage ${S.photos.apartment?'has-photo':''}">${S.photos.apartment?`<img class="room-photo" src="${esc(S.photos.apartment)}" alt="Наша квартира">`:'<div class="room-illustration"></div>'}${S.photos.himCutout?`<img class="him-cutout" src="${esc(S.photos.himCutout)}" alt="Я встречаю тебя дома">`:''}<span class="speech">Дорогая, где мы сегодня будем тусить? ♡</span></div>${choiceMarkup([{icon:'🛍',text:'Поехать в Авиапарк'},{icon:'⌂',text:'Остаться дома'},{icon:'☾',text:'Улететь на Луну'}])}<p class="hint">Выбери наш план на сегодня</p></div>`);bindChoice(0,()=>galleryReward('Наши маленькие <i>большие свидания.</i>',S.photos.aviapark,['Наш Авиапарк','Вместе даже в очередях']));}
  function backrooms(){
    frame(`${intro('ОЙ. КАЖЕТСЯ, МЫ НЕ ТУДА СВЕРНУЛИ.','Даже в бекрумс — <i>только с тобой.</i>','Наши города, наши воспоминания. И мы — вместе, даже когда земля уходит из-под ног.')}<div id="game-slot"><div class="backrooms-video-shell"><video id="backrooms-video" playsinline preload="metadata" poster="assets/effects/backrooms.png" src="assets/video/backrooms-fall.mp4"></video><span class="backrooms-label">LEVEL: US ♡</span></div><div class="scene-buttons"><button class="button" id="fall-button">Прыгнуть вместе</button></div><p class="hint" id="fall-hint">Нажми, чтобы начать наш видеопереход</p></div>`);
    const video=$('#backrooms-video');let started=false;
    listen($('#fall-button'),'click',e=>{if(started){video.play();return;}started=true;video.muted=true;video.play().then(()=>{e.target.hidden=true;$('#fall-hint').textContent='Держись за меня ♡';}).catch(()=>{started=false;toast('Нажми ещё раз, чтобы запустить видео');});});
    listen(video,'ended',()=>galleryReward('Выход нашёлся. <i>В кино.</i>',[S.photos.cinema],['Мы смотрим «Бекрумс»'],'Вернуться в наш мир'));
    listen(video,'error',()=>{$('#fall-hint').textContent='Видео не загрузилось. Обнови страницу и попробуй ещё раз.';});
    dispose.push(()=>video.pause());
  }
  function board(){
    const items=S.photos.board.length?S.photos.board:['','','','','',''];
    frame(`${intro('ЧТОБЫ НИЧЕГО НЕ ЗАБЫТЬ','На этой стене <i>живёт наше счастье.</i>','Развесь наши фотографии: выбери снимок снизу, затем свободное место на доске.')}<div id="game-slot"><div class="photo-board">${items.map((_,i)=>`<button class="board-slot" data-slot="${i}" aria-label="Место для фотографии ${i+1}">♡</button>`).join('')}</div><div class="board-tray">${items.map((_,i)=>`<button data-board-photo="${i}">Воспоминание ${i+1}</button>`).join('')}</div><p class="hint" id="board-hint">Выбери первое воспоминание</p><div id="board-next"></div></div>`);
    let selected=null,filled=0;
    listen($('#game-slot'),'click',e=>{const pick=e.target.closest('[data-board-photo]'),slot=e.target.closest('[data-slot]');if(pick&&!pick.disabled){selected=Number(pick.dataset.boardPhoto);document.querySelectorAll('[data-board-photo]').forEach(b=>b.style.background='');pick.style.background='#ffcce2';$('#board-hint').textContent='Теперь нажми на свободное место на доске';}if(slot&&!slot.classList.contains('filled')){if(selected===null){toast('Сначала выбери фотографию внизу ♡');return;}slot.classList.add('filled');slot.innerHTML=photoImage(items[selected],`Наше воспоминание ${selected+1}`);slot.setAttribute('aria-label',`Фотография ${selected+1} на доске`);slot.disabled=true;const used=$(`[data-board-photo="${selected}"]`);used.disabled=true;used.style.background='';selected=null;filled++;$('#board-hint').textContent=`Сохранено воспоминаний: ${filled} / ${items.length}`;if(filled===items.length)$('#board-next').innerHTML=nextButton('Забрать эти моменты с собой');}});
  }
  function boat(){frame(`${intro('ПЕТЕРБУРГ, СЕМЬЯ И МЫ','Поймаем <i>тот самый момент.</i>','Какой предмет вернёт нас в тот день с твоей семьёй?')}<div id="game-slot">${choiceMarkup([{icon:'⛵',text:'Кораблик'},{icon:'🎡',text:'Колесо обозрения'},{icon:'🚲',text:'Велосипед'}])}<p class="hint">Вспомни нашу прогулку по Петербургу</p></div>`);bindChoice(0,()=>galleryReward('Петербург, <i>ты и твои любимые.</i>',S.photos.boat,['Мы на кораблике','День с твоей семьёй'],'Сохранить этот тёплый день'));}
  function calendar(){
    frame(`${intro('ВРЕМЯ УМЕЕТ ЛЕТЕТЬ','Столько дней.<br><i>И один — только твой.</i>','Листай календарь с мая до сентября. Там тебя ждёт кое-что особенное.')}<div id="game-slot"><div id="calendar-wrap"></div><div class="scene-buttons" id="calendar-actions"></div><p class="hint" id="calendar-hint">Нажми «Оторвать лист», чтобы перелистнуть месяц</p></div>`);
    let month=0,busy=false;const months=['Май','Июнь','Июль','Август','Сентябрь'];
    function paint(){const sep=month===4;const days=[31,30,31,31,30][month];$('#calendar-wrap').innerHTML=`<div class="calendar"><div class="calendar-month">${months[month]}</div><div class="calendar-body"><div class="calendar-words">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:(new Date(S.birthday.year||2026,4+month,1).getDay()+6)%7},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>sep&&S.birthday.day===i+1?`<button data-birthday aria-label="День рождения ${i+1} сентября">${i+1} ♡</button>`:`<span>${i+1}</span>`).join('')}${sep&&!S.birthday.day?'<button class="birthday-only" data-birthday>♡ Твой день рождения ♡</button>':''}</div></div><div class="calendar-paper">${sep?'сегодня мир стал лучше ♡':'каждый день — чуть ближе к тебе'}</div></div>`;$('#calendar-actions').innerHTML=sep?'':'<button class="button light" id="tear-calendar">Оторвать лист</button>';$('#calendar-hint').textContent=sep?'Нажми на отметку дня рождения':`До твоего месяца осталось: ${4-month}`;}
    paint();listen($('#game-slot'),'click',e=>{if(e.target.closest('[data-birthday]'))go(17);if(e.target.closest('#tear-calendar')&&!busy){busy=true;$('.calendar').classList.add('tearing');later(()=>{month++;paint();busy=false;},350);}});
  }
  function greeting(){
    const hasVideo=Boolean(S.birthday.video);
    frame(`${intro('С ДНЁМ РОЖДЕНИЯ, МОЯ ЛЮБИМАЯ','Закрой глаза.<br><i>А теперь — открой.</i>','У меня есть кое-что, что я хочу сказать тебе сам.')}<div id="game-slot"><div class="greeting" id="greeting"><div class="film-header"><span>Полина, с днём рождения ♡</span><button id="close-film" aria-label="Вернуться к квесту">×</button></div><span class="film-flower flower-left">✿</span><span class="film-flower flower-right">✿</span>${hasVideo?`<video id="greeting-video" controls playsinline preload="metadata" src="${esc(S.birthday.video)}"></video>`:'<div class="greeting-placeholder"><b>♡</b>Здесь я поздравлю тебя сам.<br><small>Добавим твоё видеопоздравление.</small></div>'}<div class="eye-lid top"></div><div class="eye-lid bottom"></div><div class="film-footer"><span>♡ для самого любимого человека ♡</span><button id="return-from-film">Вернуться в нашу историю</button></div></div><div class="scene-buttons"><button class="button pink" id="open-eyes">Открыть глаза</button></div><div id="greeting-next"></div><p class="hint">${hasVideo?'Можно смотреть со звуком. Фоновая музыка подождёт.':'В черновике здесь место для видео; само поздравление ещё нужно прислать.'}</p></div>`);
    let wasPlaying=false,opened=false;const video=$('#greeting-video');
    function resumeAudio(){if(wasPlaying){playMusic();wasPlaying=false;}}
    if(video){listen(video,'play',()=>{if(!audio.paused){wasPlaying=true;pauseMusic();}});listen(video,'pause',resumeAudio);listen(video,'ended',resumeAudio);dispose.push(()=>{video.pause();resumeAudio();});}
    const film=$('#greeting');
    function closeFilm(){video?.pause();film.classList.remove('film-fullscreen');document.body.classList.remove('watching-film');if(document.fullscreenElement===film)document.exitFullscreen?.().catch(()=>{});}
    listen($('#close-film'),'click',closeFilm);listen($('#return-from-film'),'click',closeFilm);
    listen(document,'keydown',e=>{if(e.key==='Escape'&&film.classList.contains('film-fullscreen'))closeFilm();});
    dispose.push(()=>{document.body.classList.remove('watching-film');if(document.fullscreenElement===film)document.exitFullscreen?.().catch(()=>{});});
    listen($('#open-eyes'),'click',e=>{if(opened)return;opened=true;film.classList.add('awake','film-fullscreen');document.body.classList.add('watching-film');film.requestFullscreen?.().catch(()=>{});e.target.remove();if(video){if(!audio.paused){wasPlaying=true;pauseMusic();}video.play().catch(()=>toast('Нажми ▶ на самом видео, чтобы включить поздравление'));}later(()=>{$('#greeting-next').innerHTML=nextButton('И это ещё не всё');},2000);});
  }
  function metro(){frame(`${intro('СНОВА В МОСКВУ. СНОВА К НАМ.','На какой станции <i>мы выйдем?</i>','Вспомни название, с которого начиналась наша дорога к квартире.')}<div id="game-slot">${choiceMarkup([{icon:'Ⓜ',text:'Нахабино'},{icon:'Ⓜ',text:'Курская'},{icon:'Ⓜ',text:'Аэропорт'}])}<p class="hint">Найди нашу станцию</p></div>`);bindChoice(0,()=>{$('#game-slot').innerHTML=`<div class="boarding-pass"><div><span>СЛЕДУЮЩАЯ ОСТАНОВКА</span><b>Нахабино</b></div><span style="font-size:42px;color:var(--pink)">⌂</span></div><p style="text-align:center;font:29px var(--hand)">Осталось совсем немного. Я уже рядом.</p>${nextButton('Пойти домой')}`;});}
  function finale(){frame(`${intro('ЭТО НЕ КОНЕЦ','Наша история <i>только начинается.</i>')}<div class="final-letter"><h2>${esc(S.herName)}, моя любимая.</h2><p>${esc(S.finalText)}</p><div class="letter-sign">${S.hisName?`Твой ${esc(S.hisName)}`:'Твой человек'}. Всегда. ♡</div></div><div class="end-heart">♡</div><div class="scene-buttons"><button class="button" data-action="start">Я бы снова выбрал тебя</button><button class="button light" data-action="album">Открыть все наши фотографии</button></div><p class="replay-note">Увидимся на Новый год. А пока — я обнимаю тебя этим маленьким миром.</p>`);}
  const albumNames={'chelyabinsk':'Первый Челябинск','farewell':'До скорой встречи','moscow-first':'Первая Москва','aviapark':'Наш Авиапарк','petersburg':'Петербург','birthday':'Твой день рождения','moscow-again':'Снова Москва'};
  document.body.insertAdjacentHTML('beforeend','<dialog id="album-dialog"><div class="dialog-top"><span class="tiny">НАШ БОЛЬШОЙ ФОТОАЛЬБОМ</span><button class="close-button" data-close="album-dialog" aria-label="Закрыть альбом">×</button></div><h2>Все эти моменты — <i>наши.</i></h2><div class="album-tabs" id="album-tabs"></div><div id="album-photos"></div></dialog><dialog id="lightbox"><button class="close-button" data-close="lightbox" aria-label="Закрыть фотографию">×</button><img id="lightbox-image" alt="Наше воспоминание"></dialog>');
  function openAlbum(group='chelyabinsk'){
    $('#album-photos').querySelectorAll('video').forEach(v=>v.pause());
    $('#album-tabs').innerHTML=Object.keys(albumNames).map(k=>'<button data-album-group="'+k+'" class="'+(k===group?'selected':'')+'">'+albumNames[k]+'</button>').join('');
    $('#album-photos').innerHTML=photos(window.ALBUM[group],[albumNames[group]]);
    const clips=(window.MEMORY_VIDEOS||[]).filter(v=>v.group===group);
    if(clips.length)$('#album-photos').insertAdjacentHTML('beforeend','<h3 style="font:29px var(--hand);margin-top:25px">И ещё немного живых моментов ♡</h3>'+clips.map(v=>'<p class="small">'+esc(v.title)+'</p><video class="video-memory" controls playsinline preload="none" src="'+esc(v.src)+'"></video>').join(''));
    $('#album-photos').querySelectorAll('video').forEach(video=>{
      let restore=false;
      video.addEventListener('play',()=>{ $('#album-photos').querySelectorAll('video').forEach(other=>{if(other!==video)other.pause();}); if(!audio.paused){restore=true;pauseMusic();} });
      const restoreAudio=()=>{if(restore){restore=false;playMusic();}};
      video.addEventListener('pause',restoreAudio);video.addEventListener('ended',restoreAudio);
    });
    if(!$('#album-dialog').open)$('#album-dialog').showModal();
  }
  $('#album-dialog').addEventListener('close',()=>$('#album-photos').querySelectorAll('video').forEach(v=>v.pause()));
  function openPhoto(p){$('#lightbox-image').src=p.dataset.photo;$('#lightbox').showModal();}
  document.addEventListener('click',e=>{
    const close=e.target.closest('[data-close]');if(close)$('#'+close.dataset.close).close();
    if(e.target.closest('[data-action="album"]'))openAlbum();
    const group=e.target.closest('[data-album-group]');if(group)openAlbum(group.dataset.albumGroup);
    const photo=e.target.closest('[data-photo]');if(photo)openPhoto(photo);
  });
  document.addEventListener('keydown',e=>{const p=e.target.closest('[data-photo]');if(p&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openPhoto(p);}});
  const side=document.querySelector('.sidebar-bottom');
  side.insertAdjacentHTML('beforebegin',`<div class="sidebar-memories"><figure>${photoImage(S.photos.cover,'Наши маленькие моменты')}<figcaption>my favourite us ♡</figcaption></figure><figure>${photoImage(ALBUM['moscow-first'][22],'Ещё одно наше фото')}<figcaption>навсегда в сердце</figcaption></figure></div>`);
  go(0);
})();
